// Port of net.minecraft.client.sounds.SoundManager + SoundEngine to WebAudio.
//
// 26.2 has no sounds.json: the SoundEvent -> ogg[] index comes from
// /mc/sounds/index.json (generated by scanning official-assets-mc/sounds/<event>/).
// ogg files are fetched lazily and cached via decodeAudioData (never per frame).
// 3D sounds use a PannerNode with linear distance attenuation matching vanilla
// (attenuationDistance = max(volume,1) * 16, gain -> 0 at maxDistance).
//
// Browser autoplay policy: the AudioContext starts suspended; call resume()
// after the first user gesture (or autoUnlock() to bind it automatically).

import { XoroshiroRandomSource } from '../../vanilla/core/Random.js';
import {
  SOUND_ALIASES, SOUND_CATEGORIES, categoryOf,
} from './SoundEvents.js';
import { MusicManager } from './MusicManager.js';

export type SoundCategory =
  | 'master' | 'music' | 'record' | 'weather' | 'block'
  | 'hostile' | 'neutral' | 'player' | 'ambient' | 'voice';

export interface SoundOptions {
  master: number; music: number; record: number; weather: number; block: number;
  hostile: number; neutral: number; player: number; ambient: number; voice: number;
}

export const DEFAULT_SOUND_OPTIONS: SoundOptions = {
  master: 1, music: 1, record: 1, weather: 1, block: 1,
  hostile: 1, neutral: 1, player: 1, ambient: 1, voice: 1,
};

export interface SoundIndex {
  version: number;
  source?: string;
  eventCount?: number;
  fileCount?: number;
  events: Record<string, string[]>;
  categories?: Record<string, string[]>;
}

/** Minimal structural camera (yaw/pitch in degrees, MC convention). */
export interface SoundCamera {
  x: number; y: number; z: number;
  yaw: number; pitch: number;
}

/** Minimal structural level used for music situation / rain. */
export interface SoundLevel {
  isDay?(): boolean;
  getTimeOfDay?(): number;
  getRainLevel?(): number;
  getThunderLevel?(): number;
  dimension?: string;
  creative?: boolean;
  underwater?: boolean;
}

const SOUND_BASE = '/mc/sounds/';
const ATTENUATION_BLOCKS = 16;   // vanilla Sound.getAttenuationDistance default

function clamp01(v: number): number { return Math.min(1, Math.max(0, v)); }

export class SoundEngine {
  readonly options: SoundOptions;
  readonly music: MusicManager;

  private ctx: AudioContext | null = null;
  private rootGain: GainNode | null = null;
  private readonly categoryGains = new Map<SoundCategory, GainNode>();
  private readonly bufferCache = new Map<string, Promise<AudioBuffer>>();
  private readonly activeSources = new Set<AudioBufferSourceNode>();
  private readonly random = new XoroshiroRandomSource(0x50a1d2f3n);
  private index: SoundIndex | null = null;
  private unlocked = false;

  private static _instance: SoundEngine | null = null;
  static get(): SoundEngine { return this._instance ?? (this._instance = new SoundEngine()); }
  static setInstance(engine: SoundEngine | null): void { this._instance = engine; }

  constructor(options: Partial<SoundOptions> = {}) {
    this.options = { ...DEFAULT_SOUND_OPTIONS, ...options };
    this.music = new MusicManager(this);
  }

  get context(): AudioContext | null { return this.ctx; }
  get isReady(): boolean { return this.ctx !== null && this.index !== null; }
  get eventCount(): number { return this.index ? Object.keys(this.index.events).length : 0; }
  get fileCount(): number {
    return this.index ? Object.values(this.index.events).reduce((n, f) => n + f.length, 0) : 0;
  }

  /** Fetches the once-generated index and creates the audio graph. */
  async load(indexUrl = '/mc/sounds/index.json'): Promise<void> {
    if (this.index) return;
    const res = await fetch(indexUrl);
    if (!res.ok) throw new Error('failed to load ' + indexUrl);
    this.index = await res.json() as SoundIndex;

    const Ctor = window.AudioContext
      ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) throw new Error('WebAudio is not supported in this browser');
    const ctx = new Ctor();
    this.ctx = ctx;
    this.rootGain = ctx.createGain();
    this.rootGain.gain.value = this.options.master;
    this.rootGain.connect(ctx.destination);
    for (const cat of SOUND_CATEGORIES) {
      if (cat === 'master') continue;
      const g = ctx.createGain();
      g.gain.value = this.options[cat];
      g.connect(this.rootGain);
      this.categoryGains.set(cat, g);
    }
  }

  /** Must be called after the first user gesture (browser autoplay policy). */
  async resume(): Promise<void> {
    if (!this.ctx) return;
    if (this.ctx.state !== 'running') {
      try { await this.ctx.resume(); this.unlocked = true; } catch { /* ignored */ }
    } else {
      this.unlocked = true;
    }
  }

  get isUnlocked(): boolean { return this.unlocked; }

  /** Convenience: bind one-shot pointerdown/keydown listeners to resume(). */
  autoUnlock(): void {
    const unlock = () => { void this.resume(); };
    window.addEventListener('pointerdown', unlock, { once: true });
    window.addEventListener('keydown', unlock, { once: true });
  }

  hasEvent(name: string): boolean { return this.resolveEvent(name) !== null; }

  /** True only for events that have their own files (not an alias to some other sound). */
  hasRealEvent(name: string): boolean { return this.index !== null && this.index.events[name] !== undefined; }

  /** Number of play() calls per resolved event (debug / tests: `__mc.sounds.stats`). */
  readonly stats: Record<string, number> = {};

  /** Resolves a name directly or through SOUND_ALIASES to a real event id. */
  resolveEvent(name: string): string | null {
    if (!this.index) return null;
    if (this.index.events[name]) return name;
    const alias = SOUND_ALIASES[name];
    if (alias && this.index.events[alias]) return alias;
    return null;
  }

  setVolume(category: SoundCategory, value: number): void {
    const v = clamp01(value);
    this.options[category] = v;
    if (category === 'master') {
      if (this.rootGain) this.rootGain.gain.value = v;
    } else {
      const g = this.categoryGains.get(category);
      if (g) g.gain.value = v;
    }
  }

  getVolume(category: SoundCategory): number { return this.options[category]; }

  private gainFor(cat: SoundCategory): GainNode {
    return this.categoryGains.get(cat) ?? this.rootGain!;
  }

  /** Decode cache: one fetch + decodeAudioData per file, reused forever. */
  private buffer(path: string): Promise<AudioBuffer> {
    let p = this.bufferCache.get(path);
    if (!p) {
      p = fetch(SOUND_BASE + path)
        .then((r) => {
          if (!r.ok) throw new Error('sound ' + path + ' -> ' + r.status);
          return r.arrayBuffer();
        })
        .then((b) => this.ctx!.decodeAudioData(b));
      this.bufferCache.set(path, p);
    }
    return p;
  }

  /**
   * @param name   SoundEvent id (or an alias)
   * @param x,y,z  world position; omit all three for a non-positional (UI/music) sound
   * @param volume 0..1, also scales the attenuation distance like vanilla
   * @param pitch  0.5..2 (vanilla PITCH_MAX = 2)
   */
  play(
    name: string,
    x?: number, y?: number, z?: number,
    volume = 1, pitch = 1,
  ): void {
    const ctx = this.ctx;
    if (!ctx || !this.index || !this.rootGain) return;
    const event = this.resolveEvent(name);
    if (!event) return;
    const files = this.index.events[event];
    if (!files || !files.length) return;
    // A crowd of mobs must not turn into hundreds of live audio nodes (SoundEngine.java caps channels at 247).
    if (this.activeSources.size >= 64) return;
    this.stats[event] = (this.stats[event] ?? 0) + 1;
    const path = files[this.random.nextInt(files.length)];
    const vol = clamp01(volume);
    const cat = categoryOf(event);
    const is3d = x !== undefined && y !== undefined && z !== undefined;

    void this.buffer(path).then((buf) => {
      if (!this.ctx || !this.rootGain) return;
      const src = ctx.createBufferSource();
      src.buffer = buf;
      src.playbackRate.value = Math.min(2, Math.max(0.5, pitch));
      const gain = ctx.createGain();
      gain.gain.value = vol;                    // vanilla calculateVolume: clamp(volume)*category*master
      if (is3d) {
        const panner = ctx.createPanner();
        panner.panningModel = 'equalpower';
        panner.distanceModel = 'linear';        // vanilla LINEAR attenuation
        panner.refDistance = 1;
        panner.maxDistance = Math.max(ATTENUATION_BLOCKS, vol * ATTENUATION_BLOCKS);
        panner.rolloffFactor = 1;
        panner.positionX.value = x;
        panner.positionY.value = y;
        panner.positionZ.value = z;
        src.connect(gain).connect(panner).connect(this.gainFor(cat));
      } else {
        src.connect(gain).connect(this.gainFor(cat));
      }
      this.activeSources.add(src);
      src.onended = () => {
        this.activeSources.delete(src);
        try { src.disconnect(); gain.disconnect(); } catch { /* already gone */ }
      };
      src.start();
    }).catch(() => { /* missing / undecodable file: skip silently */ });
  }

  /** Per-frame listener update + music tick. No fetches happen here. */
  tick(camera?: SoundCamera | null, level?: SoundLevel | null): void {
    const ctx = this.ctx;
    if (!ctx) return;
    if (camera) {
      const l = ctx.listener;
      const yaw = (camera.yaw * Math.PI) / 180;
      const pitch = (camera.pitch * Math.PI) / 180;
      const cp = Math.cos(pitch);
      const fx = Math.sin(yaw) * cp, fy = -Math.sin(pitch), fz = Math.cos(yaw) * cp;
      // Modern AudioListener AudioParams (Safari fallback via setPosition/Orientation).
      if (l.positionX) {
        l.positionX.value = camera.x; l.positionY.value = camera.y; l.positionZ.value = camera.z;
        l.forwardX.value = fx; l.forwardY.value = fy; l.forwardZ.value = fz;
        l.upX.value = 0; l.upY.value = 1; l.upZ.value = 0;
      } else {
        const legacy = l as unknown as {
          setPosition?(x: number, y: number, z: number): void;
          setOrientation?(fx: number, fy: number, fz: number, ux: number, uy: number, uz: number): void;
        };
        legacy.setPosition?.(camera.x, camera.y, camera.z);
        legacy.setOrientation?.(fx, fy, fz, 0, 1, 0);
      }
    }
    this.music.tick(level ?? undefined);
  }

  stopAll(): void {
    for (const s of this.activeSources) {
      try { s.stop(); } catch { /* already stopped */ }
    }
    this.activeSources.clear();
  }
}
